<input required name="name" value="<?php echo e(old('name',$category->name)); ?>" class="rounded-xl border-slate-300" placeholder="Category name"><input name="slug" value="<?php echo e(old('slug',$category->slug)); ?>" class="rounded-xl border-slate-300" placeholder="stable-slug"><select name="parent_id" class="rounded-xl border-slate-300"><option value="">Top-level category</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $parent): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($parent->id); ?>" <?php if(old('parent_id',$category->parent_id)===$parent->id): echo 'selected'; endif; ?> <?php if($category->exists&&$category->id===$parent->id): echo 'disabled'; endif; ?>><?php echo e($parent->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select required name="area" class="rounded-xl border-slate-300"><?php $__currentLoopData = $areas; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if(old('area',$category->area ?: 'academics_research')===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input name="icon" maxlength="50" value="<?php echo e(old('icon',$category->icon)); ?>" class="rounded-xl border-slate-300" placeholder="Icon name"><input required type="number" min="0" max="10000" name="sort_order" value="<?php echo e(old('sort_order',$category->sort_order ?? 0)); ?>" class="rounded-xl border-slate-300" placeholder="Order"><textarea name="description" rows="2" maxlength="2000" class="rounded-xl border-slate-300 sm:col-span-2" placeholder="Description"><?php echo e(old('description',$category->description)); ?></textarea><label class="sm:col-span-2 text-xs font-bold text-slate-500">Allowed types (empty means all)<select multiple name="allowed_publication_types[]" class="mt-2 h-36 w-full rounded-xl border-slate-300"><?php $__currentLoopData = $types; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $type): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($type->id); ?>" <?php if(in_array($type->id,old('allowed_publication_types',$category->allowed_publication_types??[]))): echo 'selected'; endif; ?>><?php echo e($type->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label class="flex gap-2 text-sm"><input type="checkbox" name="is_active" value="1" <?php if(old('is_active',$category->is_active ?? true)): echo 'checked'; endif; ?> class="rounded">Active</label>
